/* helpers.js — shared materials & geometry builders for the Ancient Rome scene */
window.Roman = (function () {
  const M = {
    stone:     new THREE.MeshLambertMaterial({ color: 0xcfc4ae }),
    tuff:      new THREE.MeshLambertMaterial({ color: 0xbfae8f }),
    marble:    new THREE.MeshLambertMaterial({ color: 0xe8e4da }),
    dark:      new THREE.MeshLambertMaterial({ color: 0x4a443c }),
    brick:     new THREE.MeshLambertMaterial({ color: 0xa85c3b }),
    darkBrick: new THREE.MeshLambertMaterial({ color: 0x8f4a2e }),
    roof:      new THREE.MeshLambertMaterial({ color: 0xb2552f }),
    wood:      new THREE.MeshLambertMaterial({ color: 0x7a5a34 }),
    water:     new THREE.MeshLambertMaterial({ color: 0x2e7ea6, transparent: true, opacity: 0.8 }),
    gold:      new THREE.MeshLambertMaterial({ color: 0xd4af37 }),
    road:      new THREE.MeshLambertMaterial({ color: 0x9b8c6d, side: THREE.DoubleSide }),
    dirt:      new THREE.MeshLambertMaterial({ color: 0x8a7a58 }),
    grass:     new THREE.MeshLambertMaterial({ color: 0x71944c }),
    wall:      new THREE.MeshLambertMaterial({ color: 0x9c8a6b }),
    wallDark:  new THREE.MeshLambertMaterial({ color: 0x84735a }),
    cypress:   new THREE.MeshLambertMaterial({ color: 0x3d5a35 }),
    leaf:      new THREE.MeshLambertMaterial({ color: 0x5d7a3c }),
  };

  function box(w, h, d, mat, x, y, z, ry) {
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat || M.stone);
    m.position.set(x, y, z);
    if (ry) m.rotation.y = ry;
    return m;
  }

  function cyl(rt, rb, h, seg, mat, x, y, z, open) {
    const m = new THREE.Mesh(new THREE.CylinderGeometry(rt, rb, h, seg || 16, 1, !!open), mat || M.stone);
    m.position.set(x, y, z);
    return m;
  }

  // Triangular prism (pediment) facing +z
  function pediment(w, d, h, mat) {
    const s = new THREE.Shape();
    s.moveTo(-w / 2, 0); s.lineTo(w / 2, 0); s.lineTo(0, h); s.closePath();
    const g = new THREE.ExtrudeGeometry(s, { depth: d, bevelEnabled: false });
    g.translate(0, 0, -d / 2);
    const m = new THREE.Mesh(g, mat || M.stone);
    return m;
  }

  // Floating name label (canvas sprite)
  function makeLabel(text, scale) {
    scale = scale || 30;
    const c = document.createElement('canvas');
    c.width = 1024; c.height = 128;
    const g = c.getContext('2d');
    g.font = 'bold 64px Georgia, serif';
    g.textAlign = 'center'; g.textBaseline = 'middle';
    g.strokeStyle = 'rgba(0,0,0,0.85)'; g.lineWidth = 10;
    g.strokeText(text, 512, 64);
    g.fillStyle = '#f5e9c8';
    g.fillText(text, 512, 64);
    const tex = new THREE.CanvasTexture(c);
    const spr = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false }));
    spr.scale.set(scale, scale / 8, 1);
    return spr;
  }

  // Tall cypress tree (Roman favourite)
  function makeCypress(x, z, h) {
    h = h || 9;
    const y = window.Terrain.heightAt(x, z);
    const g = new THREE.Group();
    g.add(cyl(0.35, 0.45, h * 0.25, 6, M.wood, 0, h * 0.125, 0));
    const fol = new THREE.Mesh(new THREE.ConeGeometry(h * 0.28, h * 0.85, 7), M.cypress);
    fol.position.y = h * 0.25 + h * 0.425;
    g.add(fol);
    g.position.set(x, y, z);
    return g;
  }

  function makeTree(x, z, h) {
    h = h || 10;
    const y = window.Terrain.heightAt(x, z);
    const g = new THREE.Group();
    g.add(cyl(0.4, 0.55, h * 0.4, 6, M.wood, 0, h * 0.2, 0));
    const fol = new THREE.Mesh(new THREE.IcosahedronGeometry(h * 0.42, 0), M.leaf);
    fol.position.y = h * 0.62;
    g.add(fol);
    g.position.set(x, y, z);
    return g;
  }

  // Ribbon road strip that follows the terrain. pts = [[x,z],...]
  function roadRibbon(pts, width, mat) {
    width = width || 10; mat = mat || M.road;
    const pos = [], idx = [];
    const n = pts.length;
    for (let i = 0; i < n; i++) {
      const p = pts[i];
      const prev = i > 0 ? pts[i - 1] : p;
      const next = i < n - 1 ? pts[i + 1] : p;
      let dx = next[0] - prev[0], dz = next[1] - prev[1];
      const L = Math.hypot(dx, dz) || 1; dx /= L; dz /= L;
      const ox = -dz * width / 2, oz = dx * width / 2;
      const y = window.Terrain.heightAt(p[0], p[1]) + 0.45;
      pos.push(p[0] + ox, y, p[1] + oz, p[0] - ox, y, p[1] - oz);
    }
    for (let i = 0; i < n - 1; i++) {
      const a = i * 2;
      idx.push(a, a + 1, a + 2, a + 1, a + 3, a + 2);
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    g.setIndex(idx);
    g.computeVertexNormals();
    return new THREE.Mesh(g, mat);
  }

  // Closed loop of wall segments with towers. pts = [[x,z],...]
  function wallLoop(pts, height, thickness, mat, towerEvery, towerH) {
    height = height || 9; thickness = thickness || 4;
    mat = mat || M.wall; towerEvery = towerEvery || 6; towerH = towerH || 5;
    const group = new THREE.Group();
    const n = pts.length;
    for (let i = 0; i < n; i++) {
      const p = pts[i], q = pts[(i + 1) % n];
      const dx = q[0] - p[0], dz = q[1] - p[1];
      const len = Math.hypot(dx, dz);
      const y = Math.max(window.Terrain.heightAt(p[0], p[1]), window.Terrain.heightAt(q[0], q[1]));
      const b = box(len + 2, height, thickness, mat, (p[0] + q[0]) / 2, y + height / 2, (p[1] + q[1]) / 2);
      b.rotation.y = Math.atan2(dx, dz);
      group.add(b);
      if (i % towerEvery === 0) {
        group.add(box(thickness + 5, height + towerH, thickness + 5, mat, p[0], y + (height + towerH) / 2, p[1]));
      }
    }
    return group;
  }

  // Elongated dome (half sphere), base on y=0
  function makeDome(r, mat) {
    const m = new THREE.Mesh(new THREE.SphereGeometry(r, 28, 14, 0, Math.PI * 2, 0, Math.PI / 2), mat || M.roof);
    return m;
  }

  return { M, box, cyl, pediment, makeLabel, makeCypress, makeTree, roadRibbon, wallLoop, makeDome };
})();

/* terrain.js — historically-placed Seven Hills of Rome + the Tiber river */
window.Terrain = (function () {
  // The famous Seven Hills. City coordinate system: +x = east, +z = south.
  const HILLS = [
    { name: 'Palatine',   x:   0, z:  120, h: 42, r: 95  },  // imperial centre
    { name: 'Capitoline', x: -110, z:  -40, h: 38, r: 80  },  // religious citadel
    { name: 'Quirinal',   x:  170, z: -180, h: 32, r: 85  },  // NE — Serapis, Constantine baths
    { name: 'Viminal',    x:   60, z: -100, h: 24, r: 55  },  // small central hill, residential
    { name: 'Esquiline',  x:  260, z:    0, h: 36, r: 110 },  // E — Domus Aurea, Trajan baths
    { name: 'Caelian',    x:  120, z:  220, h: 32, r: 85  },  // SE — villas, residential
    { name: 'Aventine',   x:  -60, z:  260, h: 26, r: 75  },  // S near river, luxury zone
  ];

  // The Tiber curves through the city, bending west to enclose Campus Martius.
  const RIVER_W = 42;
  function riverX(z) { return -260 + 140 * Math.sin(z * 0.004 + 0.5); }

  function heightAt(x, z) {
    let h = 4; // flat lowland base
    for (let i = 0; i < HILLS.length; i++) {
      const hl = HILLS[i];
      const dx = x - hl.x, dz = z - hl.z;
      h += hl.h * Math.exp(-(dx * dx + dz * dz) / (2 * hl.r * hl.r));
    }
    // carve the river channel with a smooth transition bank
    const dx = x - riverX(z);
    const half = RIVER_W + 70;
    if (dx > -half && dx < half) {
      let t = 1 - Math.abs(dx) / half;
      t = t * t * (3 - 2 * t);
      h = h * (1 - t) + (-3.5) * t;
    }
    return h;
  }

  let waterMesh = null;
  function build(scene) {
    const S = 1700, SEG = 180;
    const geo = new THREE.PlaneGeometry(S, S, SEG, SEG);
    geo.rotateX(-Math.PI / 2);
    const pos = geo.attributes.position;
    const colors = [];
    const cSand = [0.74, 0.66, 0.45], cLow = [0.63, 0.61, 0.42],
          cHigh = [0.5, 0.47, 0.38], cGrass = [0.42, 0.55, 0.3];
    for (let i = 0; i < pos.count; i++) {
      const x = pos.getX(i), z = pos.getZ(i);
      const h = heightAt(x, z);
      pos.setY(i, h);
      let c = (h < 0.8) ? cSand : (h < 2.5) ? cLow : (h > 30) ? cHigh : cGrass;
      const n = Math.sin(x * 0.13) * Math.cos(z * 0.11) * 0.035;
      colors.push(c[0] + n, c[1] + n, c[2] + n);
    }
    geo.setAttribute('color', new THREE.Float32BufferAttribute(colors, 3));
    geo.computeVertexNormals();
    scene.add(new THREE.Mesh(geo, new THREE.MeshLambertMaterial({ vertexColors: true })));

    waterMesh = new THREE.Mesh(
      new THREE.PlaneGeometry(S, S),
      new THREE.MeshLambertMaterial({ color: 0x2a6f97, transparent: true, opacity: 0.82 })
    );
    waterMesh.rotation.x = -Math.PI / 2;
    waterMesh.position.y = 0.3;
    scene.add(waterMesh);
  }

  function animate(t) {
    if (waterMesh) waterMesh.position.y = 0.3 + Math.sin(t * 0.0012) * 0.15;
  }

  return { HILLS, riverX, RIVER_W, heightAt, build, animate };
})();

/* temples.js — Roman temples: high podium, front stairs, deep portico, cella,
   engaged side columns, pediment. Includes Pantheon (dome + oculus). */
window.Temples = (function () {
  const R = window.Roman, M = R.M;

  // Generic Roman temple. width (w), depth (d), floor height above podium (fh),
  // number of front columns (nc), column height (ch)
  function makeTemple(opts) {
    const w = opts.w || 24, d = opts.d || 32, fh = opts.fh || 9,
          nc = opts.nc || 6, ch = opts.ch || 8,
          mat = opts.mat || M.marble, ped = opts.ped || M.stone;
    const g = new THREE.Group();
    const podiumH = 3;
    // high podium + single front staircase
    g.add(R.box(w + 2, podiumH, d + 2, M.tuff, 0, podiumH / 2, 0));
    for (let i = 0; i < 4; i++)
      g.add(R.box(w * (1 - i * 0.08), 0.5, 1.1, M.stone, 0, 0.25 + i * 0.5, d / 2 + 1 + (3 - i) * 1.1));
    // cella (naos) behind the porch
    const cellaW = w * 0.62, cellaD = d * 0.55;
    const cella = R.box(cellaW, fh, cellaD, mat, 0, podiumH + fh / 2, -d * 0.18);
    g.add(cella);
    // free-standing front colonnade (pronaos)
    const colR = ch * 0.09;
    for (let i = 0; i < nc; i++) {
      const x = -w / 2 + w * (i / (nc - 1));
      for (const row of [0, -1]) {
        const z = d * 0.32 + row * 2.2;
        const c = R.cyl(colR, colR * 1.15, ch, 10, mat, x, podiumH + ch / 2, z);
        g.add(c);
        g.add(R.box(colR * 3, 0.7, colR * 3, mat, x, podiumH + ch + 0.35, z)); // capital
      }
    }
    // engaged (half) columns along the cella sides
    for (let i = 1; i < 5; i++) {
      const z = -d * 0.42 + d * 0.55 * (i / 4);
      for (const sx of [-1, 1])
        g.add(R.cyl(colR * 0.8, colR * 0.95, ch * 0.9, 8, mat, sx * (cellaW / 2), podiumH + ch * 0.45, z));
    }
    // architrave + pediment over the front
    g.add(R.box(w * 1.04, 1.4, 2.6, ped, 0, podiumH + ch + 1.1, d * 0.32));
    const pedm = R.pediment(w * 1.06, 2.6, w * 0.32, ped);
    pedm.position.set(0, podiumH + ch + 1.8, d * 0.32);
    g.add(pedm);
    // flat roof over the cella
    g.add(R.box(cellaW + 1, 1, cellaD + 1, ped, 0, podiumH + fh + 0.5, -d * 0.18));
    return g;
  }

  // Pantheon: cylindrical rotunda with great concrete dome + oculus, portico of 8
  function makePantheon() {
    const g = new THREE.Group();
    g.add(R.box(34, 2, 40, M.tuff, 0, 1, 0));                       // platform
    const drum = R.cyl(17, 17, 15, 32, M.stone, 0, 2 + 7.5, -4);
    g.add(drum);
    const dome = R.makeDome(17, M.stone);                           // unreinforced concrete dome
    dome.position.set(0, 2 + 15, -4);
    g.add(dome);
    const oculus = R.cyl(2.4, 2.4, 1.6, 16, M.dark, 0, 2 + 15 + 16.6, -4, true); // oculus ring
    g.add(oculus);
    g.add(R.box(3, 16.2, 3, M.dark, 0, 2 + 8, -4 - 16.2));          // dome ribs hint
    for (let i = 0; i < 8; i++) {                                   // portico
      const x = -14 + 28 * (i / 7);
      g.add(R.cyl(0.9, 1.05, 11, 12, M.marble, x, 2 + 5.5, 16));
      g.add(R.box(2.4, 0.8, 2.4, M.marble, x, 2 + 11.4, 16));
    }
    g.add(R.box(32, 1.6, 3, M.stone, 0, 2 + 12.2, 16));
    const ped = R.pediment(33, 3, 10, M.stone);
    ped.position.set(0, 2 + 13, 16);
    g.add(ped);
    for (let i = 0; i < 6; i++) g.add(R.box(7, 0.5, 1, M.stone, -15 + i * 3, 0.25 + i * 0.5, 19.5 + (5 - i)));
    const label = R.makeLabel('Pantheon', 34);
    label.position.set(0, 42, -4);
    g.add(label);
    return g;
  }

  // Round temple (Temple of Vesta type)
  function makeRoundTemple(r) {
    r = r || 5;
    const g = new THREE.Group();
    g.add(R.cyl(r + 0.6, r + 0.8, 2, 24, M.tuff, 0, 1, 0));
    for (let i = 0; i < 10; i++) {
      const a = i / 10 * Math.PI * 2;
      g.add(R.cyl(r * 0.09, r * 0.11, 5.5, 8, M.marble, Math.cos(a) * (r - 0.5), 2 + 2.75, Math.sin(a) * (r - 0.5)));
    }
    g.add(R.cyl(r * 0.6, r * 0.6, 5, 20, M.marble, 0, 2 + 2.5, 0));
    const cone = new THREE.Mesh(new THREE.ConeGeometry(r + 0.4, r * 0.8, 20), M.roof);
    cone.position.y = 2 + 5 + r * 0.4;
    g.add(cone);
    for (let i = 0; i < 4; i++)
      g.add(R.box(4 - i * 0.6, 0.4, 0.9, M.stone, 0, 0.2 + i * 0.4, r + 1 + i * 0.9));
    return g;
  }

  function place(g, x, z, ry, scene) {
    g.position.set(x, window.Terrain.heightAt(x, z) + 0.3, z);
    if (ry) g.rotation.y = ry;
    scene.add(g);
    return g;
  }

  function build(scene) {
    // Temple of Jupiter Optimus Maximus — top of the Capitoline citadel
    const jupiter = makeTemple({ w: 34, d: 44, fh: 12, nc: 8, ch: 11 });
    const lj = R.makeLabel('Temple of Jupiter Optimus Maximus', 46); lj.position.y = 40; jupiter.add(lj);
    place(jupiter, -110, -55, Math.PI, scene);

    // Pantheon — Campus Martius / Agona area
    place(makePantheon(), -140, 30, Math.PI * 0.85, scene);

    // Temple of Portunus — Forum Boarium, near the Tiber
    const port = makeTemple({ w: 15, d: 20, fh: 7, nc: 5, ch: 6.5, mat: M.marble });
    const lp = R.makeLabel('Temple of Portunus', 24); lp.position.y = 26; port.add(lp);
    place(port, riverBank(-80) + 26, -80, Math.PI * 0.8, scene);

    // Temple of Venus and Roma — between Palatine and Colosseum (Hadrian's great temple)
    const venus = makeTemple({ w: 44, d: 60, fh: 14, nc: 9, ch: 12 });
    const lv = R.makeLabel('Temple of Venus and Roma', 48); lv.position.y = 44; venus.add(lv);
    place(venus, 45, 165, Math.PI * 0.95, scene);

    // Roman Forum temples
    const saturn = makeTemple({ w: 22, d: 26, fh: 8, nc: 6, ch: 7 });
    const ls = R.makeLabel('Temple of Saturn', 26); ls.position.y = 24; saturn.add(ls);
    place(saturn, -20, 62, Math.PI * 0.85, scene);

    // Temple of Vesta & Atrium Vestae — circular shrine, eternal flame
    const vesta = makeRoundTemple(5.5);
    const lvv = R.makeLabel('Temple of Vesta', 20); lvv.position.y = 20; vesta.add(lvv);
    place(vesta, -35, 30, 0, scene);
    const flame = new THREE.Mesh(new THREE.ConeGeometry(0.7, 1.6, 8),
      new THREE.MeshLambertMaterial({ color: 0xff8c1a, emissive: 0xff6600 }));
    flame.position.set(-35, window.Terrain.heightAt(-35, 30) + 3.4, 30);
    scene.add(flame);

    // Temple of Serapis — Quirinal hill
    const serapis = makeTemple({ w: 30, d: 38, fh: 10, nc: 7, ch: 9 });
    const lser = R.makeLabel('Temple of Serapis', 36); lser.position.y = 36; serapis.add(lser);
    place(serapis, 150, -200, 0, scene);

    // Temple of Castor and Pollux — Forum, triple-arched podium
    const castor = makeTemple({ w: 24, d: 30, fh: 9, nc: 6, ch: 8 });
    const lc = R.makeLabel('Temple of Castor and Pollux', 30); lc.position.y = 32; castor.add(lc);
    place(castor, 78, 42, Math.PI * 0.9, scene);

    // Temple of Juno Regina — Aventine
    const juno = makeTemple({ w: 20, d: 24, fh: 8, nc: 6, ch: 7 });
    const ljn = R.makeLabel('Temple of Juno Regina', 24); ljn.position.y = 26; juno.add(ljn);
    place(juno, -70, 290, 0, scene);

    function riverBank(z) { return window.Terrain.riverX(z) - window.Terrain.RIVER_W; }
  }

  return { build, makeTemple, makePantheon, makeRoundTemple, place };
})();

/* colosseum.js — the Flavian Amphitheatre (Colosseum), east of the Forum */
window.Colosseum = (function () {
  const R = window.Roman, M = R.M;

  function build(scene) {
    const g = new THREE.Group();
    const EX = 1.3; // elliptical stretch along x

    // base platform flattens the ground
    g.add(R.cyl(64 * EX, 66 * EX, 4, 48, M.tuff, 0, 2, 0));
    g.add(R.cyl(62 * EX, 62 * EX, 1, 48, M.dirt, 0, 4.2, 0));

    // outer elliptical facade in two arcaded tiers
    const wallMat = M.stone.clone();
    wallMat.side = THREE.DoubleSide;
    const t1 = new THREE.Mesh(new THREE.CylinderGeometry(58, 62, 14, 48, 1, true), wallMat);
    t1.position.y = 4 + 7; t1.scale.x = EX;
    g.add(t1);
    const t2 = new THREE.Mesh(new THREE.CylinderGeometry(54, 58, 11, 48, 1, true), wallMat);
    t2.position.y = 18 + 5.5; t2.scale.x = EX;
    g.add(t2);

    // tier bands + ring of columns suggesting the arcades
    const band = new THREE.Mesh(new THREE.CylinderGeometry(60, 60, 1.6, 48, 1, true), M.darkBrick.clone());
    band.material.side = THREE.DoubleSide; band.scale.x = EX;
    g.add(band);
    for (const by of [4, 18, 29]) {
      const b = band.clone(); b.position.y = by; g.add(b);
    }
    for (const [y, r] of [[10, 63], [23, 61]]) {
      for (let i = 0; i < 48; i++) {
        const a = i / 48 * Math.PI * 2;
        const c = R.cyl(1.1, 1.25, 7, 8, M.marble, Math.cos(a) * r, y, Math.sin(a) * r * 1 / 1);
        c.scale.x = 1; // position computed on circle; ellipse via parent below
        g.add(c);
      }
    }

    // roof ring on top with a hint of the retractable awning (velarium)
    const roof = new THREE.Mesh(new THREE.RingGeometry(30, 62, 48), M.roof.clone());
    roof.material.side = THREE.DoubleSide;
    roof.rotation.x = -Math.PI / 2; roof.position.y = 30.5; roof.scale.x = EX;
    g.add(roof);

    // seating (cavea) sloping down to the arena
    const cavea = new THREE.Mesh(new THREE.CylinderGeometry(30, 48, 20, 48, 1, true), M.tuff.clone());
    cavea.material.side = THREE.DoubleSide;
    cavea.position.y = 4 + 10; cavea.scale.x = EX;
    g.add(cavea);
    // arena floor
    const floor = new THREE.Mesh(new THREE.CircleGeometry(30, 48), M.dirt.clone());
    floor.material.color.set(0xa89468);
    floor.rotation.x = -Math.PI / 2; floor.position.y = 4.6; floor.scale.x = EX;
    g.add(floor);

    // turn the column rings into ellipses: wrap whole ring groups
    // (simpler: scale the entire group's x to make everything elliptical)
    const label = R.makeLabel('Colosseum (Flavian Amphitheatre)', 52);
    label.position.y = 48;
    g.add(label);

    const x = 145, z = 95;
    g.position.set(x, window.Terrain.heightAt(x, z) - 2, z);
    g.scale.x = 1; // columns were added on a circle; make them elliptical:
    // scale whole structure in x so facade bands & cavea & columns share the ellipse
    g.scale.set(EX, 1, 1);
    // undo double-scaling on parts already scaled
    [t1, t2, band, roof, cavea, floor].forEach(m => m.scale.x /= EX);
    scene.add(g);
  }

  return { build };
})();

/* circuses.js — Circus Maximus: chariot-racing stadium in the valley
   between Palatine and Aventine, with spina, turning posts and grandstands */
window.Circuses = (function () {
  const R = window.Roman, M = R.M;

  function buildCircusMaximus(scene) {
    const g = new THREE.Group();
    const L = 150, W = 44; // track length (z axis) and width

    // flattened track bed
    g.add(R.box(W, 2, L, M.dirt, 0, 0.4, 0));
    const track = new THREE.Mesh(new THREE.PlaneGeometry(W * 0.8, L * 0.94),
      new THREE.MeshLambertMaterial({ color: 0x9c7f52 }));
    track.rotation.x = -Math.PI / 2; track.position.y = 1.45;
    g.add(track);

    // outer perimeter wall
    const wallMat = M.stone;
    g.add(R.box(W / 2 + 4, 10, L + 8, wallMat, -(W / 2) - 4, 6, 0));
    g.add(R.box(W / 2 + 4, 10, L + 8, wallMat, (W / 2) + 4, 6, 0));
    g.add(R.box(W, 10, 6, wallMat, 0, 6, -(L / 2) - 4));

    // tiered grandstands (cavea) along both long sides
    for (const s of [-1, 1]) {
      for (let i = 0; i < 6; i++) {
        const t = i / 6;
        g.add(R.box(6, 1.6, L * 0.9, i % 2 ? M.tuff : M.stone,
          s * (W / 2 - 2 - t * 4.5), 1.5 + i * 1.6, 0));
        // spectator row hint
      }
      // upper colonnaded terrace
      g.add(R.box(8, 6, L * 0.9, M.stone, s * (W / 2 + 7), 14, 0));
      for (let i = 0; i < 14; i++)
        g.add(R.cyl(0.5, 0.6, 5, 8, M.marble, s * (W / 2 + 10.2), 14, -L / 2 * 0.9 + i * (L * 0.9 / 13)));
    }
    // semicircular tier at the far end
    const bowl = new THREE.Mesh(
      new THREE.CylinderGeometry(W / 2 - 4, W / 2 + 6, 14, 24, 1, true, 0, Math.PI), M.tuff.clone());
    bowl.material.side = THREE.DoubleSide;
    bowl.rotation.y = -Math.PI / 2; bowl.rotation.z = 0;
    bowl.position.set(0, 8, L / 2);
    g.add(bowl);

    // the spina: central raised race track with obelisks and turning posts
    g.add(R.box(5, 2, L * 0.8, M.stone, 0, 2.4, 0));
    for (const ez of [-L * 0.38, L * 0.38]) {
      g.add(R.box(3, 2, 3, M.marble, 0, 4, ez));
      const ob = new THREE.Mesh(new THREE.CylinderGeometry(0.5, 1.1, 16, 4), M.gold);
      ob.rotation.y = Math.PI / 4; ob.position.set(0, 4 + 2 + 8, ez);
      g.add(ob);
    }
    // three torus-shaped turning posts (metae)
    for (const mz of [-6, 0, 6]) {
      const meta = new THREE.Mesh(new THREE.TorusGeometry(2.2, 0.7, 8, 16), M.stone);
      meta.rotation.x = Math.PI / 2; meta.position.set(0, 5.5, mz);
      g.add(meta);
    }
    // starting gates at the near end (porta pompae hint)
    g.add(R.box(2, 9, 2, M.stone, -6, 5.5, -L / 2 + 1));
    g.add(R.box(2, 9, 2, M.stone, 6, 5.5, -L / 2 + 1));
    g.add(R.box(14, 1.6, 2, M.darkBrick, 0, 10.3, -L / 2 + 1));

    const label = R.makeLabel('Circus Maximus', 48);
    label.position.set(0, 34, 0);
    g.add(label);

    const x = 15, z = 200;
    g.position.set(x, window.Terrain.heightAt(x, z) - 1, z);
    scene.add(g);
  }

  // A smaller circus in the Campus Martius (Circus Flaminius)
  function buildCircusFlaminius(scene) {
    const g = new THREE.Group();
    const L = 90, W = 28;
    g.add(R.box(W, 2, L, M.dirt, 0, 0.4, 0));
    for (const s of [-1, 1])
      for (let i = 0; i < 4; i++)
        g.add(R.box(4, 1.4, L * 0.85, i % 2 ? M.tuff : M.stone, s * (W / 2 - 1 - i * 3), 1.3 + i * 1.4, 0));
    const spina = R.box(3, 1.6, L * 0.75, M.stone, 0, 2, 0);
    g.add(spina);
    const label = R.makeLabel('Circus Flaminius', 26);
    label.position.y = 22;
    g.add(label);
    const x = -195, z = -60;
    g.position.set(x, window.Terrain.heightAt(x, z) - 0.5, z);
    scene.add(g);
  }

  function build(scene) {
    buildCircusMaximus(scene);
    buildCircusFlaminius(scene);
  }

  return { build };
})();

/* bathes.js — public baths (thermae): frigidarium, tepidarium, caldarium,
   hypocaust heating, pools, apses. Baths of Caracalla, Trajan, Constantine. */
window.Bathes = (function () {
  const R = window.Roman, M = R.M;

  function makeBathes(scale) {
    scale = scale || 1;
    const g = new THREE.Group();

    // Tepidarium — central rectangular hall, open roof showing the pool
    g.add(R.box(26, 10, 40, M.stone, 0, 5, 0));
    g.add(R.box(20, 0.5, 34, M.dark, 0, 10.2, 0));
    const pool1 = new THREE.Mesh(new THREE.BoxGeometry(10, 0.4, 24), M.water.clone());
    pool1.material.color.set(0x3a8ab8);
    pool1.position.set(0, 3, 0);
    g.add(pool1);
    g.add(R.box(12, 2.5, 26, M.marble, 0, 1.25, 0)); // pool wall
    for (let i = 0; i < 6; i++) {                     // colonnade inside
      g.add(R.cyl(0.5, 0.6, 9, 8, M.marble, -9, 5, -15 + i * 6));
      g.add(R.cyl(0.5, 0.6, 9, 8, M.marble, 9, 5, -15 + i * 6));
    }

    // Frigidarium — square hall with semicircular apse at west end
    g.add(R.box(20, 12, 34, M.stone, -28, 6, 0));
    const apseW = new THREE.Mesh(new THREE.CylinderGeometry(10, 10, 12, 16, 1, false, 0, Math.PI), M.stone);
    apseW.rotation.y = Math.PI / 2; apseW.position.set(-38, 6, 0);
    g.add(apseW);
    const coldPool = new THREE.Mesh(new THREE.BoxGeometry(8, 0.4, 16), M.water.clone());
    coldPool.material.color.set(0x2f6f9a);
    coldPool.position.set(-30, 2.5, 0);
    g.add(coldPool);

    // Caldarium — semicircular hot room with dome and hot pool
    g.add(R.box(18, 11, 34, M.stone, 28, 5.5, 0));
    const apseE = new THREE.Mesh(new THREE.CylinderGeometry(9, 9, 11, 16, 1, false, Math.PI, Math.PI), M.stone);
    apseE.rotation.y = Math.PI / 2; apseE.position.set(37, 5.5, 0);
    g.add(apseE);
    const dome = R.makeDome(9, M.roof);
    dome.position.set(37, 11, 0);
    g.add(dome);
    const hotPool = new THREE.Mesh(new THREE.BoxGeometry(6, 0.4, 12), M.water.clone());
    hotPool.material.color.set(0x5aa8c8);
    hotPool.position.set(33, 2.5, 0);
    g.add(hotPool);

    // Hypocaust underfloor heating — pilae (stacked brick columns) visible under a lifted floor section
    g.add(R.box(30, 0.6, 8, M.brick, 0, 0.3, 26));
    for (let i = 0; i < 6; i++)
      for (let j = 0; j < 2; j++)
        g.add(R.box(1, 3, 1, M.darkBrick, -12 + i * 4.8, 1.9, 24 + j * 4));
    g.add(R.box(30, 0.5, 8, M.stone, 0, 3.6, 26));

    // entrance portico
    for (let i = 0; i < 5; i++)
      g.add(R.cyl(0.6, 0.75, 8, 10, M.marble, -12 + i * 6, 4, -23));
    g.add(R.box(30, 1.4, 3, M.stone, 0, 8.7, -23));
    g.add(R.pediment(30, 3, 4, M.stone).translateY(9.4).translateZ(-23));

    // roof slabs over the side halls (gaps left to show the pools)
    g.add(R.box(22, 1, 36, M.roof, -28, 12.5, 0));
    g.add(R.box(20, 1, 36, M.roof, 28, 12.5, 0));

    g.scale.setScalar(scale);
    return g;
  }

  function place(g, name, x, z, ry, scene) {
    g.position.set(x, window.Terrain.heightAt(x, z), z);
    if (ry) g.rotation.y = ry;
    const label = R.makeLabel(name, 40);
    label.position.y = 26;
    g.add(label);
    scene.add(g);
  }

  function build(scene) {
    // Baths of Caracalla — great complex, NE near Quirinal
    place(makeBathes(1.6), 'Baths of Caracalla (Thermae Antoniniana)', 240, -280, -0.5, scene);
    // Baths of Trajan — Esquiline, above the river
    place(makeBathes(1.3), 'Baths of Trajan', 330, 70, -0.9, scene);
    // Baths of Constantine — Quirinal summit
    place(makeBathes(1.1), 'Baths of Constantine', 200, -140, 0.3, scene);
  }

  return { build };
})();

/* walls.js — Servian Wall (4th c. BCE, tuff, ~10.6 m high) and the
   Aurelian Wall (271 CE, brick-faced concrete, 381 towers, ~30 m apart) */
window.Walls = (function () {
  const R = window.Roman, M = R.M;

  // Irregular closed circuit around a centre
  function circuit(cx, cz, rx, rz, n, wobble) {
    const pts = [];
    for (let i = 0; i < n; i++) {
      const a = i / n * Math.PI * 2;
      const w = 1 + wobble * Math.sin(3 * a + 1) + wobble * 0.6 * Math.cos(2 * a);
      pts.push([cx + Math.cos(a) * rx * w, cz + Math.sin(a) * rz * w]);
    }
    return pts;
  }

  function build(scene) {
    // Servian Wall: encloses the Seven Hills, tuff, 10.6 m high, ~12 km
    const servian = circuit(60, 20, 380, 320, 72, 0.05);
    scene.add(R.wallLoop(servian, 10.6, 5, M.tuff, 5, 4));
    const ls = R.makeLabel('Servian Wall (390 BCE)', 40);
    ls.position.set(60, 40, -300);
    scene.add(ls);

    // Aurelian Wall: the great brick-faced circuit, 7.2–10.6 m high, 381 towers
    const aurelian = circuit(40, 0, 520, 460, 96, 0.04);
    scene.add(R.wallLoop(aurelian, 9, 4, M.brick, 7, 5));
    const la = R.makeLabel('Aurelian Wall (271 CE)', 40);
    la.position.set(40, 42, 430);
    scene.add(la);

    window.ROME_WALLS = { servian, aurelian }; // shared with gates.js
  }

  return { build, circuit };
})();

/* gates.js — the great gates of the Aurelian Wall, aligned with the
   consular roads (viae) radiating out of Rome. */
window.Gates = (function () {
  const R = window.Roman, M = R.M;

  // A city gate: flanking towers + arched passage(s)
  function makeGate(towers, threeBays) {
    const g = new THREE.Group();
    const tH = 16;
    const bayW = 6;
    const count = threeBays ? 4 : 2;      // piers
    const span = (count - 1) * (bayW + 5);
    for (let i = 0; i < count; i++) {
      const x = -span / 2 + i * (bayW + 5);
      g.add(R.box(5, tH, towers ? 12 : 9, M.brick, x, tH / 2, 0));
    }
    for (let i = 0; i < count - 1; i++) {
      const x = -span / 2 + i * (bayW + 5) + (bayW + 5) / 2;
      g.add(R.box(bayW + 5, 3.4, towers ? 12 : 9, M.stone, x, tH - 1.7, 0)); // lintel
      // arch hints under the lintel
      g.add(R.box(bayW, 5, 0.8, M.dark, x, 2.5, 5.5));
      g.add(R.box(bayW, 5, 0.8, M.dark, x, 2.5, -5.5));
    }
    if (towers) {
      // big corner round towers (e.g. Porta San Sebastiano)
      for (const sx of [-1, 1]) {
        const t = R.cyl(6, 7, tH + 6, 16, M.brick, sx * (span / 2 + 9), (tH + 6) / 2, 0);
        g.add(t);
      }
    }
    return g;
  }

  function build(scene) {
    const pts = window.Walls.circuit(40, 0, 520, 460, 96, 0.04);
    const N = pts.length;
    const at = function (deg) {
      const i = Math.round(deg / 360 * N) % N;
      return pts[i];
    };
    // +z is south. Consular roads out of each gate.
    const list = [
      { name: 'Porta San Sebastiano (Appia)',   deg: 90,  towers: true,  bays: 3 }, // Via Appia
      { name: 'Porta San Paolo (Ostiensis)',   deg: 140, towers: false, bays: 1 }, // to Ostia
      { name: 'Porta Maggiore (Praenestina)',  deg: 100, towers: false, bays: 2 }, // Claudian aqueduct arch
      { name: 'Porta Flaminia (del Popolo)',   deg: 275, towers: true,  bays: 3 }, // Via Flaminia
      { name: 'Porta Salaria',                 deg: 245, towers: false, bays: 1 },
      { name: 'Porta Pinciana',                deg: 205, towers: false, bays: 1 },
      { name: 'Porta Tiburtina',               deg: 335, towers: false, bays: 2 }, // Via Tiburtina
      { name: 'Porta Esquilina',               deg: 8,   towers: false, bays: 2 },
      { name: 'Porta Latina',                  deg: 30,  towers: false, bays: 2 }, // Via Latina
    ];
    for (const gt of list) {
      const p = at(gt.deg);
      const gate = makeGate(gt.towers, gt.bays > 1);
      const y = window.Terrain.heightAt(p[0], p[1]);
      gate.position.set(p[0], y, p[1]);
      // face outward from the city centre (40, 0)
      gate.rotation.y = Math.atan2(p[0] - 40, p[1] - 0);
      scene.add(gate);
      const label = R.makeLabel(gt.name, 30);
      label.position.set(p[0], y + 26, p[1]);
      scene.add(label);
    }
  }

  return { build, makeGate };
})();

