window.Buildings = (function () {
  const R = window.Roman, M = R.M;

  function label(text, y, g) {
    const l = R.makeLabel(text, y > 30 ? 44 : 26);
    l.position.y = y;
    g.add(l);
  }

  function buildForum(scene) {
