  }

  function buildDomusAurea(scene) {
    // Nero's Golden House + gardens, Esquiline
    const g = new THREE.Group();
    g.add(R.box(46, 14, 36, M.gold, 0, 7, 0));
    g.add(R.box(48, 1, 38, M.stone, 0, 14.5, 0));
    const dome = R.makeDome(12, M.roof);
    dome.position.set(0, 15, 0);
    g.add(dome);
    for (let i = 0; i < 10; i++) {                          // garden cypresses
      g.add(R.makeCypress(i % 5 === 0 ? -1 : 1 * 30, 26 + (i % 5) * 4, 10));
    }
    label('Domus Aurea (Golden House)', 30, g);
    const x = 290, z = -40;
    g.position.set(x, window.Terrain.heightAt(x, z) - 0.5, z);
    scene.add(g);
  }

  function buildTabularium(scene) {
    // Archive hall on the foot of the Capitoline, facing the Forum
    const g = new THREE.Group();
    g.add(R.box(44, 12, 10, M.stone, 0, 6, 0));
    for (let i = 0; i < 10; i++) {
      g.add(R.box(2, 8, 1.5, M.tuff, -19 + i * 4.2, 2, 5.5));
      g.add(R.box(2.6, 1.2, 1.8, M.stone, -19 + i * 4.2, 6.8, 5.5));
    }
    label('Tabularium (State Archives)', 20, g);
    const x = -90, z = 8;
    g.position.set(x, window.Terrain.heightAt(x, z) - 0.5, z);
    scene.add(g);
  }

  // Insulae — multi-storey brick apartment blocks filling the residential streets
  function buildInsulae(scene) {
    let seed = 42;
    const rnd = function () { seed = (seed * 16807) % 2147483647; return seed / 2147483647; };
    const skip = function (x, z, r) { return (x - r[0]) * (x - r[0]) + (z - r[1]) * (z - r[1]) < 900; };
    const reserved = [[20, 50], [145, 95], [15, 200], [-140, 30], [240, -280], [330, 70], [200, -140]];
    const group = new THREE.Group();
    for (let x = -330; x <= 460; x += 42) {
      for (let z = -320; z <= 400; z += 42) {
        if (rnd() < 0.35) continue;
        const px = x + rnd() * 14, pz = z + rnd() * 14;
        const h = window.Terrain.heightAt(px, pz);
        if (h < 2 || h > 20) continue;
        for (const r of reserved) { if (skip(px, pz, r)) break; continue; }
        let ok = true;
        for (const r of reserved) if (skip(px, pz, r)) { ok = false; break; }
        if (!ok) continue;
        const w = 10 + rnd() * 8, d = 10 + rnd() * 8, bh = 9 + rnd() * 14;
        const m = rnd() < 0.7 ? M.brick : M.tuff;
        group.add(R.box(w, bh, d, m, px, h + bh / 2, pz, rnd() * 0.4 - 0.2));
        group.add(R.box(w + 0.6, 0.8, d + 0.6, m === M.brick ? M.darkBrick : M.stone, px, h + bh + 0.4, pz));
      }
    }
    scene.add(group);
  }

  function build(scene) {
    buildForum(scene);
    buildPalatine(scene);
    buildDomusAurea(scene);
    buildTabularium(scene);
    buildInsulae(scene);
  }

  return { build };
})();

/* obelisks.js — Egyptian obelisks set up by Roman emperors: Forum,
   Circus Maximus spina, Pantheon front, Campus Martius */
window.Obelisks = (function () {
  const R = window.Roman, M = R.M;

  function makeObelisk(h) {
    h = h || 20;
    const g = new THREE.Group();
    g.add(R.box(3, 2.4, 3, M.marble, 0, 1.2, 0));            // socle
    g.add(R.box(2.2, 1.2, 2.2, M.tuff, 0, 2.9, 0));
    const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.55, 1.15, h, 4), M.gold.clone());
    shaft.material.color.set(0xc9a86a);
    shaft.rotation.y = Math.PI / 4;
    shaft.position.y = 3.5 + h / 2;
    g.add(shaft);
    const tip = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.6, 1.8, 4), M.gold);
    tip.rotation.y = Math.PI / 4;
    tip.position.y = 3.5 + h + 0.9;
    g.add(tip);
    return g;
  }

  function place(name, x, z, h, scene) {
    const g = makeObelisk(h);
    g.position.set(x, window.Terrain.heightAt(x, z), z);
    scene.add(g);
    const label = R.makeLabel(name, 22);
    label.position.set(x, window.Terrain.heightAt(x, z) + h + 8, z);
    scene.add(label);
  }

  function build(scene) {
    place('Obelisk of the Forum', 15, 25, 22, scene);
    place('Obelisk of the Campus Martius', -175, 90, 26, scene);
    place('Pantheon Obelisk', -172, 45, 16, scene);
    // the great spina obelisks of the Circus Maximus
    const cx = 15, cz = 200;
    for (const dz of [-57, 57]) {
      const g = makeObelisk(24);
      g.position.set(cx, window.Terrain.heightAt(cx, cz) - 0.5 + 4, cz + dz);
      scene.add(g);
    }
  }

  return { build, makeObelisk };
})();

