/* triumphalArches.js — victory arches: Titus, Septimius Severus,
   Constantine, Augustus. Bays with true arched openings. */
window.TriumphalArches = (function () {
  const R = window.Roman, M = R.M;

  // One arched bay as an extruded slab (rectangle with semicircular hole)
  function archBay(w, h, d, mat) {
    const s = new THREE.Shape();
    s.moveTo(-w / 2, 0); s.lineTo(w / 2, 0); s.lineTo(w / 2, h); s.lineTo(-w / 2, h); s.closePath();
    const ar = w * 0.38, archH = Math.min(ar * 1.5, h * 0.65);
    const hole = new THREE.Path();
    hole.moveTo(-ar, 0);
    hole.absarc(0, archH - ar, ar, Math.PI, 0, true);
    hole.lineTo(ar, 0);
    hole.lineTo(-ar, 0);
    s.holes.push(hole);
    const g = new THREE.ExtrudeGeometry(s, { depth: d, bevelEnabled: false });
    g.translate(0, 0, -d / 2);
    return new THREE.Mesh(g, mat || M.stone);
  }

  function makeArch(h, bays, mat) {
    h = h || 10; bays = bays || 1;
    const g = new THREE.Group();
    const bayW = 7, gap = 3;
    const total = bays * bayW + (bays - 1) * gap;
    for (let i = 0; i < bays; i++) {
      const x = -total / 2 + bayW / 2 + i * (bayW + gap);
      const slab = archBay(bayW, h, bays > 1 ? 6 : 8, mat || M.stone);
      slab.position.x = x;
      g.add(slab);
    }
    // side cheeks + entablature/attic
    for (const sx of [-1, 1])
      g.add(R.box(1.2, h + 3, bays > 1 ? 8 : 9, M.tuff, sx * (total / 2 + 0.6), (h + 3) / 2, 0));
    g.add(R.box(total + 3.5, 2, bays > 1 ? 8 : 9, M.stone, 0, h + 1, 0));
    g.add(R.box(total + 2.5, 2.5, bays > 1 ? 6 : 7, M.tuff, 0, h + 3.5, 0)); // attic
    return g;
  }

  function place(name, x, z, ry, h, bays, scene) {
    const g = makeArch(h, bays);
    g.position.set(x, window.Terrain.heightAt(x, z), z);
    if (ry) g.rotation.y = ry;
    scene.add(g);
    const label = R.makeLabel(name, 26);
    label.position.set(x, window.Terrain.heightAt(x, z) + h + 10, z);
    scene.add(label);
  }

  function build(scene) {
    // Arch of Titus — end of the Via Sacra, through the Temple of Septimius Severus
    place('Arch of Titus (81 CE)', 55, 55, 0.6, 9, 1, scene);
    // Arch of Septimius Severus — three bays, crossing the Via Sacra
    place('Arch of Septimius Severus (203 CE)', 12, 60, Math.PI / 2, 12, 3, scene);
    // Arch of Constantine — before the Colosseum
    place('Arch of Constantine (315 CE)', 108, 118, -0.9, 13, 3, scene);
    // Arch of Augustus — Caelian hill
    place('Arch of Augustus', 150, 175, 0.4, 10, 1, scene);
  }

  return { build, makeArch };
})();

/* aqueducts.js — masonry aqueducts carrying water over the valleys,
   brick arches on a channel (aqua ductus) reaching fountains & baths. */
window.Aqueducts = (function () {
  const R = window.Roman, M = R.M;

  // Cross-section of a vaulted bay: rectangle with a semicircular hole
  function bayGeometry(w, h, depth) {
    const s = new THREE.Shape();
    const ar = w * 0.42, archH = Math.min(ar * 1.6, h * 0.7);
    s.moveTo(-w / 2, 0); s.lineTo(w / 2, 0); s.lineTo(w / 2, h); s.lineTo(-w / 2, h); s.closePath();
    const hole = new THREE.Path();
    hole.moveTo(-ar, 0);
    hole.absarc(0, archH - ar, ar, Math.PI, 0, true);
    hole.lineTo(ar, 0);
    hole.lineTo(-ar, 0);
    s.holes.push(hole);
    const g = new THREE.ExtrudeGeometry(s, { depth: depth, bevelEnabled: false });
    g.translate(0, 0, -depth / 2);
    return g;
  }

  // One tier of arches following a list of [x,z] points
  function tier(pts, h, w, mat) {
    const g = new THREE.Group();
    const bayLen = w * 0.92;
    for (let i = 0; i < pts.length - 1; i++) {
      const a = pts[i], b = pts[i + 1];
      const dx = b[0] - a[0], dz = b[1] - a[1];
      const len = Math.hypot(dx, dz);
      const n = Math.max(1, Math.round(len / (w * 1.4)));
      for (let j = 0; j < n; j++) {
        const t = (j + 0.5) / n;
        const x = a[0] + dx * t, z = a[1] + dz * t;
        const y = Math.max(1.5, window.Terrain.heightAt(x, z));
        const bay = new THREE.Mesh(bayGeometry(w, h, bayLen), mat);
        bay.position.set(x, y, z);
        bay.rotation.y = Math.atan2(dx, dz);
        g.add(bay);
      }
    }
    return g;
  }

  function makeAqueduct(name, pts, h, w, scene) {
    const g = new THREE.Group();
    // lower arcade
    const lower = tier(pts, h, w, M.brick);
    g.add(lower);
    // upper channel wall carrying the water
    for (let i = 0; i < pts.length - 1; i++) {
      const a = pts[i], b = pts[i + 1];
      const dx = b[0] - a[0], dz = b[1] - a[1];
      const len = Math.hypot(dx, dz);
      const x = (a[0] + b[0]) / 2, z = (a[1] + b[1]) / 2;
      const yBase = Math.max(1.5, window.Terrain.heightAt(x, z));
      const wall = R.box(1.6, 3.2, len + 2, M.stone, 0, 0, 0, Math.atan2(dx, dz) + Math.PI / 2);
      wall.position.set(x + dz / len * 2.6, yBase + h + 1.6, z - dx / len * 2.6);
      g.add(wall);
      const wall2 = wall.clone();
      wall2.position.set(x - dz / len * 2.6, yBase + h + 1.6, z + dx / len * 2.6);
      g.add(wall2);
      // water in the channel
      const water = R.box(3.4, 0.5, len + 2, M.water, 0, 0, 0, Math.atan2(dx, dz) + Math.PI / 2);
      water.position.set(x, yBase + h + 3.1, z);
      g.add(water);
    }
    const label = R.makeLabel(name, 44);
    label.position.set(pts[1][0], 55, pts[1][1]);
    g.add(label);
    scene.add(g);
  }

  function build(scene) {
    // Aqua Claudia/Verginis — across the NW valley from the hills to the city
    makeAqueduct('Aqua Claudia Aqueduct',
      [[-580, -350], [-340, -280], [-80, -200], [140, -130], [340, -90]], 16, 8, scene);
    // Aqua Marcia — crossing the southern valley
    makeAqueduct('Aqua Marcia Aqueduct',
      [[-480, 330], [-220, 360], [40, 400], [300, 430], [480, 470]], 14, 7, scene);
  }

  return { build };
})();

/* fountains.js — public fountains (nympheum & basin fountains) fed by
   the aqueducts: Forum, Campus Martius, Palatine */
window.Fountains = (function () {
  const R = window.Roman, M = R.M;

  function makeFountain(scale) {
    scale = scale || 1;
    const g = new THREE.Group();
    // great basin
    g.add(R.cyl(9, 10, 1.6, 24, M.stone, 0, 0.8, 0));
    const water = new THREE.Mesh(new THREE.CircleGeometry(8.2, 24), M.water.clone());
    water.material.color.set(0x3f97c2);
    water.rotation.x = -Math.PI / 2; water.position.y = 1.45;
    g.add(water);
    // marble rim columns
    for (let i = 0; i < 10; i++) {
      const a = i / 10 * Math.PI * 2;
      g.add(R.cyl(0.4, 0.5, 3.4, 8, M.marble, Math.cos(a) * 8.8, 3.3, Math.sin(a) * 8.8));
    }
    // middle tier
    g.add(R.cyl(1.2, 1.4, 5, 10, M.marble, 0, 3.9, 0));
    g.add(R.cyl(4.5, 5, 1, 16, M.stone, 0, 6.6, 0));
    const water2 = new THREE.Mesh(new THREE.CircleGeometry(3.9, 16), M.water.clone());
    water2.material.color.set(0x3f97c2);
    water2.rotation.x = -Math.PI / 2; water2.position.y = 7.05;
    g.add(water2);
    // upper basin + jet
    g.add(R.cyl(0.6, 0.7, 3, 8, M.marble, 0, 8.6, 0));
    g.add(R.cyl(2, 2.2, 0.7, 12, M.stone, 0, 10.3, 0));
    const jet = new THREE.Mesh(new THREE.ConeGeometry(0.5, 2.6, 8), M.water.clone());
    jet.material.color.set(0x9fd8ef);
    jet.position.y = 12;
    g.add(jet);
    g.scale.setScalar(scale);
    return g;
  }

  function place(name, x, z, s, scene) {
    const g = makeFountain(s);
    g.position.set(x, window.Terrain.heightAt(x, z) + 0.2, z);
    scene.add(g);
    const label = R.makeLabel(name, 20);
    label.position.y = 18 * s;
    g.add(label);
  }

  function build(scene) {
    place('Fountain of the Forum (Nymphaeum)', 38, 30, 1, scene);
    place('Great Fountain of the Campus Martius', -165, 10, 1.6, scene);
    place('Fountain of the Palatine', 60, 105, 1.2, scene);
  }

  return { build };
})();

